function renderProgress() {
  const completed = tasks.filter(t => t.score > 0).length
  const average = Math.round(tasks.filter(t => t.score > 0).reduce((sum, t) => sum + t.score, 0) / Math.max(1, completed))
  return `<main class="shell inner-shell">${renderPageHeader('05', 'Прогресс.', 'Следите за тем, какие принципы уже освоены и где ещё можно усилить навык.', 'progress')}
    <section class="progress-dashboard reveal"><article class="progress-card profile-progress"><div class="progress-avatar">${profile.photo ? `<img src="${profile.photo}" alt="">` : profile.name.slice(0,1).toUpperCase()}</div><div><span class="card-kicker">ОБУЧАЮЩИЙСЯ</span><h2>${profile.name}</h2><p>${profile.role}</p></div><div class="progress-big">${Math.round(completed / tasks.length * 100)}<small>%</small></div></article><article class="progress-card average-progress"><span class="card-kicker">СРЕДНИЙ РЕЗУЛЬТАТ</span><strong>${average}</strong><div class="big-progress-line"><i style="width:${average}%"></i></div><p>${completed} из ${tasks.length} модулей имеют результат.</p></article></section>
    <section class="skills-grid reveal">${tasks.map(task => `<article class="skill-card"><div class="skill-icon accent-${task.accent}">${uiIcon(task.icon as keyof typeof UI_ICON_SVGS)}</div><div><b>${task.title}</b><span>${task.score ? `${task.score} / 100` : 'Ещё не начато'}</span></div><div class="skill-bar"><i style="width:${task.score || 0}%"></i></div></article>`).join('')}</section>
  </main>`
}

